import React, { useMemo, useState } from 'react';
import { Link as RouterLink, useSearchParams } from 'react-router-dom';
import {
    Box, Typography, Container, Paper, TextField, Button, MenuItem, Grid, Alert,
    ToggleButton, ToggleButtonGroup, CircularProgress, Breadcrumbs, Link, useTheme
} from '@mui/material';
import HomeIcon from '@mui/icons-material/Home';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import { submitMasjidRequest } from '../services/masjidService';

// "Claim this masjid" / "Add a masjid" (Mosque Directory step 4, 2026-10-20).
// Linked from the static masjid pages (/masjids/**) with ?kind=claim&osm=&name=&url=&lat=&lon=&region=&country=,
// and from the directory with ?kind=add. Sent to POST /v1/alexa/masjid-requests; the admin
// reviews it at alexa.imuslimlife.com/admin/masjid-requests.

const REGIONS = {
    us: [['AL', 'Alabama'], ['AK', 'Alaska'], ['AZ', 'Arizona'], ['AR', 'Arkansas'], ['CA', 'California'], ['CO', 'Colorado'], ['CT', 'Connecticut'], ['DE', 'Delaware'], ['DC', 'District of Columbia'], ['FL', 'Florida'], ['GA', 'Georgia'], ['HI', 'Hawaii'], ['ID', 'Idaho'], ['IL', 'Illinois'], ['IN', 'Indiana'], ['IA', 'Iowa'], ['KS', 'Kansas'], ['KY', 'Kentucky'], ['LA', 'Louisiana'], ['ME', 'Maine'], ['MD', 'Maryland'], ['MA', 'Massachusetts'], ['MI', 'Michigan'], ['MN', 'Minnesota'], ['MS', 'Mississippi'], ['MO', 'Missouri'], ['MT', 'Montana'], ['NE', 'Nebraska'], ['NV', 'Nevada'], ['NH', 'New Hampshire'], ['NJ', 'New Jersey'], ['NM', 'New Mexico'], ['NY', 'New York'], ['NC', 'North Carolina'], ['ND', 'North Dakota'], ['OH', 'Ohio'], ['OK', 'Oklahoma'], ['OR', 'Oregon'], ['PA', 'Pennsylvania'], ['PR', 'Puerto Rico'], ['RI', 'Rhode Island'], ['SC', 'South Carolina'], ['SD', 'South Dakota'], ['TN', 'Tennessee'], ['TX', 'Texas'], ['UT', 'Utah'], ['VT', 'Vermont'], ['VA', 'Virginia'], ['WA', 'Washington'], ['WV', 'West Virginia'], ['WI', 'Wisconsin'], ['WY', 'Wyoming']],
    ca: [['AB', 'Alberta'], ['BC', 'British Columbia'], ['MB', 'Manitoba'], ['NB', 'New Brunswick'], ['NL', 'Newfoundland and Labrador'], ['NS', 'Nova Scotia'], ['NT', 'Northwest Territories'], ['NU', 'Nunavut'], ['ON', 'Ontario'], ['PE', 'Prince Edward Island'], ['QC', 'Quebec'], ['SK', 'Saskatchewan'], ['YT', 'Yukon']],
};

const MasjidRequestPage = () => {
    const theme = useTheme();
    const [params] = useSearchParams();
    const initial = useMemo(() => {
        const country = ['us', 'ca'].includes(params.get('country')) ? params.get('country') : 'us';
        const region = String(params.get('region') || '').toUpperCase();
        return {
            kind: params.get('kind') === 'claim' ? 'claim' : 'add',
            target: params.get('kind') === 'claim' ? {
                osmId: params.get('osm') || null, name: params.get('name') || '', url: params.get('url') || null,
                latitude: params.get('lat') || null, longitude: params.get('lon') || null,
            } : null,
            name: params.get('name') || '',
            country,
            region: REGIONS[country].some(([c]) => c === region) ? region : '',
        };
    }, [params]);

    const [kind, setKind] = useState(initial.kind);
    const [f, setF] = useState({
        name: initial.name, address: '', city: '', region: initial.region, country: initial.country, website: '', masjidPhone: '',
        contactName: '', email: '', role: '', phone: '', notes: '', website2: '',
    });
    const [sending, setSending] = useState(false);
    const [error, setError] = useState(null);
    const [done, setDone] = useState(false);
    const set = (k) => (e) => setF({ ...f, [k]: e.target.value, ...(k === 'country' ? { region: '' } : {}) });
    const claimingListed = kind === 'claim' && initial.target?.url;

    const submit = async (e) => {
        e.preventDefault();
        setSending(true);
        setError(null);
        try {
            await submitMasjidRequest({
                kind,
                target: kind === 'claim' ? initial.target : null,
                masjid: { name: f.name, address: f.address, city: f.city, region: f.region, country: f.country, website: f.website, phone: f.masjidPhone },
                contact: { name: f.contactName, email: f.email, role: f.role, phone: f.phone },
                notes: f.notes,
                website2: f.website2,
            });
            setDone(true);
            window.scrollTo(0, 0);
        } catch (err) {
            setError(err.message || 'Could not send. Please try again.');
        } finally {
            setSending(false);
        }
    };

    return (
        <Container maxWidth="md" sx={{ py: { xs: 4, md: 6 } }}>
            <Breadcrumbs aria-label="breadcrumb" sx={{ mb: 2 }}>
                <Link component={RouterLink} to="/" sx={{ display: 'flex', alignItems: 'center' }} underline="hover" color="inherit">
                    <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" /> Home
                </Link>
                <Link component={RouterLink} to="/mosque-directory" underline="hover" color="inherit">Mosque Directory</Link>
                <Typography color="text.primary">{kind === 'claim' ? 'Claim a masjid' : 'Add a masjid'}</Typography>
            </Breadcrumbs>

            {done ? (
                <Paper elevation={2} sx={{ p: { xs: 3, md: 5 }, borderRadius: 3, textAlign: 'center' }}>
                    <CheckCircleIcon sx={{ fontSize: 64, color: theme.palette.success.main }} />
                    <Typography variant="h4" component="h1" sx={{ mt: 2 }} gutterBottom>JazakAllahu khayran</Typography>
                    <Typography color="text.secondary" sx={{ maxWidth: 520, mx: 'auto' }}>
                        {kind === 'claim'
                            ? `We received your request to manage ${f.name}. We check every claim with the masjid before giving access, then email you at ${f.email} how to sign in and add your iqamah times.`
                            : `We received ${f.name}. Once we have checked it, it appears in the directory within a day or two.`}
                    </Typography>
                    <Button variant="contained" component={RouterLink} to="/mosque-directory" sx={{ mt: 3 }}>Back to the directory</Button>
                </Paper>
            ) : (
                <Paper component="form" onSubmit={submit} elevation={2} sx={{ p: { xs: 2.5, md: 4 }, borderRadius: 3 }}>
                    <Typography variant="h4" component="h1" gutterBottom sx={{ fontSize: { xs: '1.8rem', md: '2.2rem' } }}>
                        {kind === 'claim' ? (claimingListed ? `Claim ${initial.target.name || 'this masjid'}` : 'Claim your masjid') : 'Add a masjid'}
                    </Typography>
                    <Typography color="text.secondary" sx={{ mb: 3 }}>
                        {kind === 'claim'
                            ? 'Masjids on Masjid Connect publish their own iqamah and Jumu’ah times and announcements here, and the people who follow them get reminders on their Echo. It’s free.'
                            : 'Tell us about a masjid or musalla that is missing from the directory. We check it before it appears.'}
                    </Typography>

                    {!claimingListed && (
                        <ToggleButtonGroup value={kind} exclusive onChange={(e, v) => v && setKind(v)} size="small" sx={{ mb: 3 }} aria-label="Request type">
                            <ToggleButton value="add">Add a missing masjid</ToggleButton>
                            <ToggleButton value="claim">I run this masjid</ToggleButton>
                        </ToggleButtonGroup>
                    )}

                    <Typography variant="h6" gutterBottom>The masjid</Typography>
                    <Grid container spacing={2} sx={{ mb: 3 }}>
                        <Grid item xs={12}><TextField label="Masjid name" value={f.name} onChange={set('name')} required fullWidth inputProps={{ maxLength: 120 }} /></Grid>
                        {!claimingListed && (
                            <>
                                <Grid item xs={12}><TextField label="Street address" value={f.address} onChange={set('address')} required={kind === 'add'} fullWidth inputProps={{ maxLength: 200 }} /></Grid>
                                <Grid item xs={12} sm={5}><TextField label="Town / city" value={f.city} onChange={set('city')} required={kind === 'add'} fullWidth inputProps={{ maxLength: 80 }} /></Grid>
                                <Grid item xs={6} sm={4}>
                                    <TextField select label={f.country === 'ca' ? 'Province' : 'State'} value={f.region} onChange={set('region')} required={kind === 'add'} fullWidth>
                                        {REGIONS[f.country].map(([c, n]) => <MenuItem key={c} value={c}>{n}</MenuItem>)}
                                    </TextField>
                                </Grid>
                                <Grid item xs={6} sm={3}>
                                    <TextField select label="Country" value={f.country} onChange={set('country')} fullWidth>
                                        <MenuItem value="us">USA</MenuItem>
                                        <MenuItem value="ca">Canada</MenuItem>
                                    </TextField>
                                </Grid>
                            </>
                        )}
                        <Grid item xs={12} sm={7}><TextField label="Masjid website" value={f.website} onChange={set('website')} fullWidth inputProps={{ maxLength: 300 }} helperText={kind === 'claim' ? 'Helps us confirm the claim quickly' : ''} /></Grid>
                        <Grid item xs={12} sm={5}><TextField label="Masjid phone" value={f.masjidPhone} onChange={set('masjidPhone')} fullWidth inputProps={{ maxLength: 40 }} /></Grid>
                    </Grid>

                    <Typography variant="h6" gutterBottom>You</Typography>
                    <Grid container spacing={2} sx={{ mb: 2 }}>
                        <Grid item xs={12} sm={6}><TextField label="Your name" value={f.contactName} onChange={set('contactName')} required fullWidth inputProps={{ maxLength: 80 }} /></Grid>
                        <Grid item xs={12} sm={6}><TextField label="Your email" type="email" value={f.email} onChange={set('email')} required fullWidth inputProps={{ maxLength: 120 }} helperText={kind === 'claim' ? 'Use your masjid email if you have one: you sign in with it' : ''} /></Grid>
                        {kind === 'claim' && <Grid item xs={12} sm={6}><TextField label="Your role at the masjid" placeholder="Imam, board member, volunteer…" value={f.role} onChange={set('role')} required fullWidth inputProps={{ maxLength: 80 }} /></Grid>}
                        <Grid item xs={12} sm={6}><TextField label="Your phone (optional)" value={f.phone} onChange={set('phone')} fullWidth inputProps={{ maxLength: 40 }} /></Grid>
                        <Grid item xs={12}><TextField label="Anything else? (optional)" value={f.notes} onChange={set('notes')} fullWidth multiline minRows={2} inputProps={{ maxLength: 1000 }} /></Grid>
                    </Grid>
                    {/* Honeypot: hidden from people; bots fill it. */}
                    <Box aria-hidden="true" sx={{ position: 'absolute', left: '-10000px', width: 1, height: 1, overflow: 'hidden' }}>
                        <label>Leave this empty <input tabIndex={-1} autoComplete="off" value={f.website2} onChange={set('website2')} /></label>
                    </Box>

                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        We use your details only to check this request and reply to you. See our <Link href="/privacy-policy/">privacy policy</Link>.
                    </Typography>
                    {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                    <Button type="submit" variant="contained" size="large" disabled={sending} startIcon={sending ? <CircularProgress size={18} color="inherit" /> : null}>
                        {kind === 'claim' ? 'Send claim' : 'Send'}
                    </Button>
                </Paper>
            )}
        </Container>
    );
};

export default MasjidRequestPage;
